import{_ as t,o as a,c as o,a3 as n}from"./chunks/framework.BlfGB29P.js";const g=JSON.parse('{"title":"Invoices — User Guide","description":"","frontmatter":{"head":[["meta",{"property":"og:title","content":"Invoices — User Guide | EloSync Docs"}],["meta",{"property":"og:description","content":"Official documentation for the EloSync SaaS Platform."}],["meta",{"property":"og:url","content":"https://docs.elosync.com/user-guide/invoices"}],["meta",{"property":"og:image","content":"https://docs.elosync.com/og-image.svg"}],["meta",{"name":"twitter:card","content":"summary_large_image"}],["meta",{"name":"twitter:title","content":"Invoices — User Guide | EloSync Docs"}],["meta",{"name":"twitter:description","content":"Official documentation for the EloSync SaaS Platform."}],["meta",{"name":"twitter:image","content":"https://docs.elosync.com/og-image.svg"}],["link",{"rel":"canonical","href":"https://docs.elosync.com/user-guide/invoices"}]]},"headers":[],"relativePath":"user-guide/invoices.md","filePath":"user-guide/invoices.md","lastUpdated":1786668537000}'),s={name:"user-guide/invoices.md"};function i(r,e,d,l,c,h){return a(),o("div",null,[...e[0]||(e[0]=[n('<h1 id="invoices-—-user-guide" tabindex="-1">Invoices — User Guide <a class="header-anchor" href="#invoices-—-user-guide" aria-label="Permalink to &quot;Invoices — User Guide&quot;">​</a></h1><h2 id="who-can-use-invoices" tabindex="-1">Who can use Invoices <a class="header-anchor" href="#who-can-use-invoices" aria-label="Permalink to &quot;Who can use Invoices&quot;">​</a></h2><p>Your workspace must have the <strong>Invoices</strong> module installed (free from Marketplace — not auto-installed, and <strong>no other module is required first</strong>). Your role must include the relevant permissions (<code>view</code>, <code>create</code>, <code>update</code>, <code>delete</code>, <code>restore</code>, <code>force.delete</code>, <code>assign</code>, <code>send</code>, <code>void</code> as needed).</p><p>Without <strong>assign</strong>, you only see invoices assigned to you.</p><h2 id="list-table" tabindex="-1">List &amp; table <a class="header-anchor" href="#list-table" aria-label="Permalink to &quot;List &amp; table&quot;">​</a></h2><p>Open <strong>Invoices</strong> from the sidebar (<strong>Billing</strong>). Search by title or number, filter by status or assignee, toggle <strong>My invoices</strong> or <strong>Overdue only</strong>, and switch KPI cards (Total, My Invoices, Draft, Sent, Overdue) to quick-filter the table. The table shows total, balance due, due date, and the <strong>latest note</strong>; hover a truncated preview to read the full note.</p><ul><li>An <strong>Overdue</strong> badge appears next to the status badge for unpaid, sent/partial invoices past their due date</li><li>Users with <strong>restore</strong> can filter <strong>Active / Include deleted / Deleted only</strong>, then <strong>Restore</strong> a soft-deleted invoice from the row menu</li><li><strong>Delete permanently</strong> requires <code>invoices.force.delete</code> — granted to the workspace <strong>owner</strong> by default</li></ul><h2 id="create-edit" tabindex="-1">Create &amp; edit <a class="header-anchor" href="#create-edit" aria-label="Permalink to &quot;Create &amp; edit&quot;">​</a></h2><ol><li>Click <strong>New invoice</strong></li><li>Enter a title, optional contact/company link (when Contacts/Companies is installed), optional linked quotation, currency (defaults to your workspace currency; full shared currency list), issue date, due date, and notes</li><li>Add line items (description, quantity, unit price, tax rate) — subtotal, tax, and total are calculated automatically</li><li>Optionally set an assignee (requires <strong>assign</strong>)</li><li>Save</li></ol><p>Edit from the row menu or the detail sheet while the invoice is still <strong>Draft</strong>. Editing replaces the full line-item list. After <strong>Send</strong>, content is locked; use status actions and assignment instead.</p><h2 id="status-workflow" tabindex="-1">Status workflow <a class="header-anchor" href="#status-workflow" aria-label="Permalink to &quot;Status workflow&quot;">​</a></h2><p>An invoice starts in <strong>Draft</strong>. Move it forward with:</p><ul><li><strong>Send</strong> (<code>draft → sent</code>) — marks the invoice as sent in the CRM (does not e-mail the customer or attach a PDF yet); sets the issue date to today if it wasn&#39;t set</li><li><strong>Void</strong> — available from Draft or Sent only; permanently cancels the invoice. Blocked once any payment has been posted or any credit note applied — void the payments first (an applied credit note can&#39;t be undone at all), since an invoice moves to <strong>Partial</strong> the moment either happens</li></ul><p><strong>Partial</strong> and <strong>Paid</strong> are not user-driven — they&#39;re set automatically as <a href="/user-guide/payments">Payments</a> are posted against the invoice, or as <a href="/user-guide/credit-notes">Credit Notes</a> are applied to it.</p><p>Invalid transitions (e.g. sending an already-voided invoice) are rejected with a validation error.</p><h2 id="assignment" tabindex="-1">Assignment <a class="header-anchor" href="#assignment" aria-label="Permalink to &quot;Assignment&quot;">​</a></h2><p>Users with <strong>assign</strong> can set or clear the assignee from the detail sheet or the create/edit form. The assignee receives an in-app notification when someone else assigns them.</p><h2 id="notes-activity" tabindex="-1">Notes &amp; activity <a class="header-anchor" href="#notes-activity" aria-label="Permalink to &quot;Notes &amp; activity&quot;">​</a></h2><ul><li><strong>Notes</strong> — free-form notes on the invoice</li><li><strong>Activity</strong> — timeline of create, update, assignment, status change, note, void, and delete/restore events</li></ul><h2 id="related-payments-and-credit-notes" tabindex="-1">Related payments and credit notes <a class="header-anchor" href="#related-payments-and-credit-notes" aria-label="Permalink to &quot;Related payments and credit notes&quot;">​</a></h2><p>If the <a href="/user-guide/payments">Payments</a> module is installed and you have <code>payments.view</code>, the invoice detail sheet shows a <strong>Related payments</strong> link to jump to the Payments module and record or review payments against this invoice. If <a href="/user-guide/credit-notes">Credit Notes</a> is installed and you have <code>credit-notes.view</code>, a <strong>Credit notes</strong> link does the same for credit notes issued against this invoice.</p><h2 id="what-s-not-here-yet" tabindex="-1">What&#39;s not here yet <a class="header-anchor" href="#what-s-not-here-yet" aria-label="Permalink to &quot;What&#39;s not here yet&quot;">​</a></h2><p>Generating invoice PDFs and e-mailing invoices to customers are planned but not part of this module yet — see the <a href="/getting-started/product-roadmap">Product Roadmap</a>.</p>',23)])])}const m=t(s,[["render",i]]);export{g as __pageData,m as default};
